package webui

// workerInventoryTemplate replaces the original registration-only view with a
// continuously refreshed fleet inventory while retaining manual onboarding.
const workerInventoryTemplate = `
{{define "workers"}}<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Worker fleet · Aiori Compute</title>{{template "styles" .}}
<style>
.worker-page{max-width:1440px;width:100%;margin:0 auto;min-width:0}.worker-grid{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(280px,.7fr);gap:20px;align-items:start}.worker-table-scroll{max-height:560px;overflow:auto;overscroll-behavior:contain;border:1px solid var(--line,#e5e7eb);border-radius:12px}.worker-table{width:100%;min-width:850px;border-collapse:separate;border-spacing:0}.worker-table th{position:sticky;top:0;z-index:2;background:var(--surface,#fff);text-align:left;font-size:11px;text-transform:uppercase;letter-spacing:.05em;color:var(--muted,#64748b);padding:13px;border-bottom:1px solid var(--line,#e5e7eb)}.worker-table td{padding:14px 13px;border-bottom:1px solid var(--line,#e5e7eb);font-size:13px;vertical-align:middle}.worker-table tr:last-child td{border:0}.worker-table tbody tr:hover{background:var(--surface-muted,#f8fafc)}.worker-id{font:12px ui-monospace,SFMono-Regular,Menlo,monospace;overflow-wrap:anywhere}.worker-muted{display:block;color:var(--muted,#64748b);font-size:11px;margin-top:4px;overflow-wrap:anywhere}.worker-state{display:inline-flex;padding:5px 9px;border-radius:999px;font-size:11px;font-weight:700;background:#fef3c7;color:#92400e}.worker-state.healthy{background:#dcfce7;color:#166534}.worker-state.stale{background:#ffedd5;color:#9a3412}.worker-state.unavailable{background:#fee2e2;color:#991b1b}.worker-empty{padding:34px 20px;text-align:center;color:var(--muted,#64748b)}.worker-memory{min-width:100px}.worker-memory-track{height:6px;background:#e2e8f0;border-radius:99px;overflow:hidden;margin-top:6px}.worker-memory-fill{height:100%;background:#0f766e}.worker-scroll-note{font-size:11px;color:var(--muted,#64748b);margin-top:8px}@media(max-width:960px){.worker-grid{grid-template-columns:1fr}}@media(max-width:600px){.worker-table-scroll{max-height:420px}}
</style></head><body class="app-body"><a class="skip-link" href="#main-content">Skip to main content</a><div class="app-shell">{{template "sidebar" .}}<main class="main-area" id="main-content"><header class="topbar"><div class="breadcrumbs">Workspace / <strong>Worker inventory</strong></div><span class="env-pill">LIVE AGENT HEALTH</span></header><div class="content"><div class="worker-page">
<div class="page-heading"><div><div class="eyebrow">Compute fleet</div><h1>Worker inventory</h1><p>Agent enrollment, heartbeat freshness, hypervisor readiness, and capacity. Refresh to update heartbeat freshness and capacity.</p></div></div>
{{if .Notice}}<div class="notice" role="status">{{.Notice}}</div>{{end}}{{if .Error}}<div class="notice error" role="alert">{{.Error}}</div>{{end}}
<div class="worker-grid">
<section class="section-card"><div class="section-head"><div><h2 class="section-title">Registered nodes</h2><div class="section-subtitle">A node is healthy only when its authenticated heartbeat confirms the hypervisor probe</div></div><div class="field-actions"><span class="status">{{len .Workers}} nodes</span><a class="aws-btn" href="/workers">Refresh status</a></div></div>
{{if .Workers}}<div class="worker-table-scroll" role="region" aria-label="Worker nodes" tabindex="0"><table class="worker-table"><thead><tr><th>Node</th><th>Agent status</th><th>Last heartbeat</th><th>Memory available / cap</th><th>Agent endpoint</th><th>Action</th></tr></thead><tbody>{{range .Workers}}<tr><td><strong>{{.Name}}</strong><span class="worker-muted worker-id">{{.ID}}</span></td><td><span class="worker-state {{.State}}">{{.State}}</span></td><td>{{if .LastHeartbeat.IsZero}}Never{{else}}{{.LastHeartbeat.Format "2006-01-02 15:04:05 UTC"}}{{end}}</td><td class="worker-memory">{{divMiB .AvailableMemoryBytes}} / {{divMiB .MemoryLimitBytes}} MiB<div class="worker-memory-track"><div class="worker-memory-fill" style="width:{{memoryPercent .AvailableMemoryBytes .MemoryLimitBytes}}%"></div></div></td><td><span class="worker-id">{{.Endpoint}}</span></td><td><form method="post" action="/workers/{{.ID}}/delete" onsubmit="return confirm('Remove this worker registration? This does not stop or terminate the EC2 instance.')"><input type="hidden" name="csrf_token" value="{{$.CSRFToken}}"><button class="btn btn-secondary" type="submit">Deregister</button></form></td></tr>{{end}}</tbody></table></div><p class="worker-scroll-note">Scroll within the inventory table to view all nodes and columns.</p>{{else}}<div class="worker-empty"><strong>No workers have enrolled yet.</strong><p>Launch an EC2 node with bootstrap configured. It will appear here after its first authenticated heartbeat.</p><a href="/aws">Go to AWS EC2 →</a></div>{{end}}</section>
<section class="section-card"><div class="section-head"><div><h2 class="section-title">Automatic enrollment</h2><div class="section-subtitle">Preferred for EC2-managed nodes</div></div></div><div class="callout">A bootstrapped EC2 agent identifies itself using its instance ID and advertises its private agent endpoint in each authenticated heartbeat. The controller persists the node on first contact. The node remains unavailable until the Cloud Hypervisor and /dev/kvm probe succeeds.</div><p class="section-subtitle">EC2 lifecycle state is shown separately on the AWS page. A stopped instance will eventually become stale; an unhealthy hypervisor can report while EC2 itself remains running.</p><a href="/aws">Manage EC2 instances →</a></section>
</div>
<section class="section-card" style="margin-top:20px"><div class="section-head"><div><h2 class="section-title">Register an existing worker manually</h2><div class="section-subtitle">Use only for workers not created through the EC2 bootstrap workflow</div></div></div><form method="post" action="/workers" class="form-grid"><input type="hidden" name="csrf_token" value="{{.CSRFToken}}"><div class="field"><label for="worker-id">Worker ID</label><input id="worker-id" name="id" required maxlength="128" pattern="[A-Za-z0-9][A-Za-z0-9._-]*" placeholder="worker-a"></div><div class="field"><label for="worker-name">Display name</label><input id="worker-name" name="name" required maxlength="128" placeholder="Worker A"></div><div class="field"><label for="worker-endpoint">Agent endpoint</label><input id="worker-endpoint" name="endpoint" type="url" required placeholder="http://10.0.1.12:9090"></div><div class="field"><label for="worker-memory">Memory cap (MiB)</label><input id="worker-memory" name="memory_limit_mib" type="number" min="1" max="1048576" required value="4096"></div><button class="btn btn-primary" type="submit">Register existing worker</button></form></section>
</div></div></main></div><script src="/assets/ui.js" defer></script></body></html>{{end}}`
